// scripts/sync-from-foundry.mjs
import fs from 'fs/promises';
import path from 'path';

// This script automates the synchronization of contract ABIs and addresses
// from the Foundry backend to the React frontend.

// --- CONFIGURATION ---
// Path to the JSON file generated by Foundry's deployment script.
const DEPLOYED_CONTRACTS_JSON = 'rwa-soberano-evolve/deployed-contracts.json';
// Base path for the Foundry project.
const FOUNDRY_BASE_PATH = 'rwa-soberano-evolve';
// Destination directory for the ABIs in the frontend.
const FRONTEND_ABI_DIR = 'frontend/src/abis';
// Path to the .env file for the frontend.
const FRONTEND_ENV_FILE = 'frontend/.env';
// --- END CONFIGURATION ---

async function main() {
  try {
    console.log('Starting synchronization from Foundry to Frontend...');

    // 1. Read the deployed contracts JSON file.
    const contractsJsonContent = await fs.readFile(DEPLOYED_CONTRACTS_JSON, 'utf-8');
    const deployedContracts = JSON.parse(contractsJsonContent);
    console.log('Successfully read deployed-contracts.json.');

    let envFileContent = '# This file is auto-generated by scripts/sync-from-foundry.mjs\n';
    envFileContent += '# Do not edit this file manually.\n\n';

    // 2. Ensure the frontend ABI directory exists.
    await fs.mkdir(FRONTEND_ABI_DIR, { recursive: true });

    // 3. Process each contract from the JSON file.
    for (const [contractName, contractInfo] of Object.entries(deployedContracts)) {
      // --- ABI Synchronization ---
      const sourceAbiPath = path.join(FOUNDRY_BASE_PATH, contractInfo.abiPath);
      const destinationAbiPath = path.join(FRONTEND_ABI_DIR, `${contractName}.json`);
      
      await fs.copyFile(sourceAbiPath, destinationAbiPath);
      console.log(`- Copied ABI for ${contractName} to ${destinationAbiPath}`);

      // --- Environment Variable Generation ---
      // Convert contract name to a VITE-compatible env var name (e.g., DocumentRegistry -> VITE_DOCUMENT_REGISTRY_ADDRESS)
      const envVarName = `VITE_${contractName.replace(/([A-Z])/g, '_$1').toUpperCase()}_ADDRESS`;
      envFileContent += `${envVarName}=${contractInfo.address}\n`;
      console.log(`- Added ${envVarName} to frontend .env content.`);
    }

    // 4. Write the generated .env file to the frontend directory.
    await fs.writeFile(FRONTEND_ENV_FILE, envFileContent);
    console.log(`\nSuccessfully generated ${FRONTEND_ENV_FILE}`);

    console.log('\nSynchronization complete!');

  } catch (error) {
    console.error('Synchronization failed:', error);
    process.exit(1);
  }
}

main();
